starterCode.css:
.composer-card {
  max-width: 400px;
  margin: 20px auto;
  padding: 24px;
  background: #FFFDF7;
  border-radius: 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  text-align: center;
  font-family: "Noto Serif SC", "STSong", serif;
}
.composer-photo {
  width: 100%;
  border-radius: 8px;
  margin-bottom: 16px;
}
.composer-card h1 {
  font-size: 1.5rem;
  color: #3D2B1F;
  margin: 0 0 8px 0;
}
.composer-card h3 {
  font-size: 1rem;
  color: #8B2E2E;
  margin: 16px 0 8px 0;
}
.composer-bio {
  font-size: 0.9rem;
  color: #6B5A4E;
  line-height: 1.6;
  margin: 0;
}
.composer-card ul {
  text-align: left;
  color: #6B5A4E;
  font-size: 0.9rem;
  line-height: 1.8;
  padding-left: 20px;
  margin: 0;
}

