}
.composer-card > p {
  font-size: 0.9rem;
  color: #6B5A4E;
  line-height: 1.6;
  margin: 0 0 16px 0;
}
.works-section {
  background: #FBF7F0;
  border-radius: 8px;
  padding: 16px;
  text-align: left;
}
.works-section h2 {
  font-size: 0.95rem;
  color: #8B2E2E;
  margin: 0 0 8px 0;
}
.works-section ul {
  color: #6B5A4E;
  font-size: 0.9rem;
  line-height: 2;
  padding-left: 20px;
  margin: 0;
}

